}
public class DogApp {
public static void main(String[] args) {
Dog dog1 = new Dog();
dog1.name = "Rocky";
dog1.breed = "Bulldog";
dog1.cost = 9999;
dog1.eat();
dog1.sleep();
dog1.bark();
}
}
